// ============================================
// VALIDATION INPUT - MCP Entity Search
// RFC-049: Multi-tenant Qdrant with MongoDB enrichment
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- CRITICAL: Multi-tenant isolation via X-Tenant-ID header ---
const tenantId = headers['x-tenant-id'] || headers['X-Tenant-ID'] || body.tenant_id || ctx.tenant_id;

if (!tenantId) {
  errors.push('X-Tenant-ID header requis pour isolation multi-tenant');
}

// --- OPTIONAL context fields (tracing only) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- REQUIRED parameters ---
const action = body.action || ctx.action;
const query = body.query || ctx.query;
const entityId = body.entity_id || ctx.entity_id;

if (!action) {
  errors.push('action requis (search ou similar)');
} else if (!['search', 'similar'].includes(action)) {
  errors.push('action doit etre search ou similar');
}

if (action === 'search' && !query) {
  errors.push('query requis pour action=search');
}

if (action === 'similar' && !entityId) {
  errors.push('entity_id requis pour action=similar');
}

// --- Qdrant configuration ---
const qdrantHost = body.qdrant_host || ctx.qdrant_host;
const qdrantPort = body.qdrant_port || ctx.qdrant_port;
const qdrantCollection = body.qdrant_collection || ctx.qdrant_collection;

// Fallback: qdrant_api_key = body.qdrant_api_key || body.api_key (legacy compatibility)
const qdrantApiKey = body.qdrant_api_key || ctx.qdrant_api_key || body.api_key || ctx.api_key || '';

if (!qdrantHost) {
  errors.push('qdrant_host requis');
}
if (!qdrantPort) {
  errors.push('qdrant_port requis');
}
if (!qdrantCollection) {
  errors.push('qdrant_collection requis');
}

// --- OpenAI for embeddings (required for action=search) ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai;

if (action === 'search' && !openaiApiKey) {
  errors.push('openai_api_key requis pour action=search');
}

// --- Optional enrichment parameters ---
const enrich = body.enrich || ctx.enrich || false;
const fields = body.fields || ctx.fields || [];
const entityType = body.entity_type || ctx.entity_type || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

const qdrantUrl = `http://${qdrantHost}:${qdrantPort}`;

return {
  valid: true,
  action: action,
  query: query || '',
  entity_id: entityId || '',
  entity_type: entityType,
  limit: body.limit || ctx.limit || 10,
  filters: body.filters || ctx.filters || {},
  enrich: enrich,
  fields: fields,
  tenant_id: tenantId,
  qdrant_url: qdrantUrl,
  qdrant_collection: qdrantCollection,
  qdrant_api_key: qdrantApiKey,
  openai_api_key: openaiApiKey || '',
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'qdrant+api',
    model: 'text-embedding-3-small',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

