// ============================================
// PREPARE ENRICHMENT - Process Qdrant results
// RFC-049: Prepare for optional MongoDB enrichment
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Handle API errors
if (input.error || input.status?.error) {
  return {
    success: false,
    qdrant_error: true,
    error_message: input.error?.message || input.status?.error || 'Qdrant search failed',
    raw_response: input,
    prevData: prevData
  };
}

// Extract results from Qdrant response
const results = (input.result || []).map(item => ({
  entity_id: item.payload?.entity_id || item.id,
  score: item.score,
  payload: item.payload || {}
}));

// Extract entity IDs for batch enrichment
const entityIds = results.map(r => r.entity_id).filter(id => id);

return {
  success: true,
  results: results,
  entity_ids: entityIds,
  enrich: prevData.enrich,
  entity_type: prevData.entity_type,
  fields: prevData.fields,
  tenant_id: prevData.tenant_id,
  prevData: prevData
};

// ============================================
// MERGE ENRICHED - Combine Qdrant with MongoDB data
// RFC-049: Join search results with entity details
// ============================================

const input = $input.first().json;
const prepData = $('Prepare Enrichment').first().json;

// If enrichment request failed, continue with Qdrant data only
if (input.error || !input.data) {
  return {
    results: prepData.results,
    enrichment_failed: true,
    enrichment_error: input.error?.message || 'Batch enrichment failed',
    prevData: prepData.prevData
  };
}

// Create lookup map from MongoDB response
const entityMap = {};
if (input.data && Array.isArray(input.data)) {
  input.data.forEach(entity => {
    if (entity._id || entity.id) {
      entityMap[entity._id || entity.id] = entity;
    }
  });
}

// Merge Qdrant results with MongoDB entities
const mergedResults = prepData.results.map(result => {
  const entityData = entityMap[result.entity_id] || null;
  return {
    entity_id: result.entity_id,
    score: result.score,
    payload: result.payload,
    entity: entityData
  };
});

return {
  results: mergedResults,
  enriched: true,
  prevData: prepData.prevData
};

// ============================================
// SKIP ENRICHMENT - Pass through Qdrant results
// ============================================

const input = $input.first().json;

const results = input.results.map(result => ({
  entity_id: result.entity_id,
  score: result.score,
  payload: result.payload,
  entity: null
}));

return {
  results: results,
  enriched: false,
  prevData: input.prevData
};

// ============================================
// FORMAT OUTPUT - MCP Entity Search
// RFC-049: Final response with _trace
// ============================================

const input = $input.first().json;
const prevData = input.prevData || $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Initialize trace
const _trace = {
  service_response: {},
  provider: 'qdrant+api',
  model: 'text-embedding-3-small',
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

try {
  // Check for Qdrant error from Prepare Enrichment
  const prepData = $('Prepare Enrichment').first().json;

  if (prepData.qdrant_error) {
    _trace.service_response = { qdrant: prepData.raw_response };
    _trace.latency_ms = Date.now() - startTime;

    return {
      json: {
        success: false,
        error: {
          code: 'SEARCH_ERROR',
          message: prepData.error_message,
          http_status: 500
        },
        meta: { provider: 'qdrant+api', collection: prevData.qdrant_collection },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: _trace
      }
    };
  }

  const results = input.results || [];

  // Apply additional filters if any
  let filtered = results;
  const filters = prevData.filters || {};

  if (filters.entity_type && prevData.entity_type) {
    filtered = filtered.filter(r => r.payload?.entity_type === prevData.entity_type);
  }

  // Populate trace
  _trace.service_response = {
    qdrant: { result_count: results.length },
    api: input.enriched ? { enriched_count: results.filter(r => r.entity).length } : null
  };
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: true,
      data: {
        results: filtered.slice(0, prevData.limit),
        total: filtered.length
      },
      meta: {
        provider: 'qdrant+api',
        collection: prevData.qdrant_collection,
        action: prevData.action,
        enriched: input.enriched || false,
        tenant_id: prevData.tenant_id
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
} catch (e) {
  _trace.service_response = { error: e.message };
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PROCESS_ERROR',
        message: 'Failed to process search results: ' + e.message,
        http_status: 500
      },
      meta: { provider: 'qdrant+api' },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}
